mapper.select:
SELECT * FROM tt_task_signal
WHERE process_status IN ('READY', 'RETRY_WAIT')
  AND next_attempt_at <= #{now}
ORDER BY next_attempt_at ASC, signal_id ASC
LIMIT #{limit}
FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE tt_task_signal SET
    process_status = 'IGNORED',
    result_code = #{resultCode},
    processed_at = #{processedAt},
    updated_at = #{updatedAt}
WHERE definition_id = #{definitionId}
  AND trigger_binding_id = #{triggerBindingId}
  AND process_status IN ('READY', 'RETRY_WAIT')

mapper.select:
SELECT signal_id FROM tt_task_signal
WHERE process_status IN ('READY', 'RETRY_WAIT')
  AND next_attempt_at <= #{now}
ORDER BY next_attempt_at ASC, signal_id ASC
LIMIT #{limit}
